    T(c, night ? S.lines[k].j.toUpperCase() : S.lines[k].j, tx, ty + (1 - hp) * H * .1, { size: night ? 30 : 34, w: 700, fam: S.f1, color: pal[1], align: al, maxW: night ? W * .78 : W * .58, ls: night ? 2 + (1 - hp) * 10 + B.lt * .8 : 0 });
