    for (let j = 0; j < 6; j++) { const yy = H * .62 + Math.pow((j + (t * .4) % 1) / 6, 2) * H * .45; c.beginPath(); c.moveTo(0, yy); c.lineTo(W, yy); c.stroke(); } c.restore();
