      X.circle(c, px, syy, 13 * (done ? .9 + .1 * pop : 1)); c.fillStyle = done ? pal[2] : act ? "#fff" : X.mix("#fff", pal[1], .06); c.fill(); c.lineWidth = 2.5; c.strokeStyle = act ? pal[2] : X.mix("#fff", pal[1], .15); c.stroke();
