    c.strokeStyle = pal[2]; c.lineCap = "round"; c.beginPath(); c.arc(rc[0], rc[1], 22, -Math.PI / 2, -Math.PI / 2 + TAU * rp); c.stroke();
    X.text(c, String(Math.ceil(60 * rp)), rc[0], rc[1] + 1, { size: 14, w: 800, fam: S.f1, color: pal[1] });
    // keyword card
